S.vapeProducts = VAPE_PRODUCTS.map(p=>({...p}));
S.vapeCart=(S.vapeCart||[]).filter(x=>S.vapeProducts.some(p=>p.id===x.productId));
S.vapeQuotes=S.vapeQuotes||[]; S.vapeInvoices=S.vapeInvoices||[];
S.vapeQuoteSequence=S.vapeQuoteSequence||0; S.vapeInvoiceSequence=S.vapeInvoiceSequence||0;
S.vapeMarkup=Math.min(25,Math.max(15,Number(S.vapeMarkup)||25));
S.vapePrivatePrices=S.vapePrivatePrices||{};
function privateEk(p){const key=matchL3Key(p);const ek=key?Number(S.vapePrivatePrices?.[key]):NaN;return Number.isFinite(ek)&&ek>=0?ek:null}
function matchL3Key(p){const x=((p?.name||'')+' '+(p?.variant||'')).toLowerCase().replace(/\s+/g,' ');for(const [needle,key] of L3_RULES)if(x.includes(needle))return key;return null}
function vapePrice(p){const ek=privateEk(p);return ek!==null?Math.round(ek*(1+S.vapeMarkup/100)*100)/100:null}
function cartCount(){return S.vapeCart.reduce((n,x)=>n+(+x.qty||0),0)}
function addToVapeCart(productId,qty=1){const p=S.vapeProducts.find(x=>x.id===productId),price=vapePrice(p);if(!p||price===null)return toast("Kein VK verfügbar – L3-Zuordnung prüfen");const q=Math.max(1,+qty||1),item=S.vapeCart.find(x=>x.productId===productId);if(item){item.qty+=q;item.price=price}else S.vapeCart.push({productId:p.id,name:p.name,variant:p.variant||"",qty:q,price});save();renderVape();toast(`${q} × ${p.name} im Warenkorb`)}
function updateVapeCart(productId,delta){const item=S.vapeCart.find(x=>x.productId===productId);if(!item)return;item.qty+=delta;if(item.qty<=0)S.vapeCart=S.vapeCart.filter(x=>x.productId!==productId);save();renderVape()}
function clearVapeCart(){S.vapeCart=[];save();renderVape();toast("Warenkorb geleert")}
function cartItems(){return S.vapeCart.map(x=>({productId:x.productId,description:x.name,variant:x.variant,qty:x.qty,unit:"Stück",price:x.price,ek:privateEk(S.vapeProducts.find(p=>p.id===x.productId))})).filter(x=>x.qty>0&&x.price>0)}
function openVapeCartQuote(){if(!cartItems().length)return toast("Warenkorb ist leer");newVapeQuoteFromCart()}
function newVapeQuoteFromCart(){S._quoteFromCart=true;newVapeQuote(null,null,null,cartItems())}
function vapeMargin(p){const ek=privateEk(p),vk=vapePrice(p);return ek!==null&&vk?1-ek/vk:null}
function setVapeMarkup(v){S.vapeMarkup=Math.min(25,Math.max(15,Number(v)||25));S.vapeCart=S.vapeCart.map(x=>{const p=S.vapeProducts.find(y=>y.id===x.productId),price=vapePrice(p);return price===null?x:{...x,price}});save();renderVape();}
function vapeProductOptions(){return '<option value="">Artikel wählen …</option>'+S.vapeProducts.map(p=>{const vk=vapePrice(p);return `<option value="${p.id}">${esc(p.name)} · ${vk===null?'VK —':`VK ${money(vk)}`}</option>`}).join('')}
function exportPrivateL3(){const payload={version:2,source:'L3-Preisliste des Nutzers',prices:S.vapePrivatePrices};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='nexaro-private-l3-prices.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function importPrivateL3(file){if(!file)return;const r=new FileReader();r.onload=()=>{try{const d=JSON.parse(r.result);if(!d||typeof d.prices!=='object')throw 0;S.vapePrivatePrices={...d.prices};S.vapeCart=S.vapeCart.map(x=>{const p=S.vapeProducts.find(y=>y.id===x.productId),price=vapePrice(p);return price===null?x:{...x,price}});save();renderVape();toast(`${Object.keys(S.vapePrivatePrices).length} L3-Preise importiert`)}catch{toast('L3-Datei konnte nicht gelesen werden')}};r.readAsText(file)}
function parseCSV(text){const rows=[];let row=[],cell='',q=false;for(let i=0;i<text.length;i++){const ch=text[i],nx=text[i+1];if(ch==='"'){if(q&&nx==='"'){cell+='"';i++}else q=!q}else if((ch===','||ch===';')&&!q){row.push(cell);cell=''}else if((ch==='\n'||ch==='\r')&&!q){if(ch==='\r'&&nx==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell=''}else cell+=ch}if(cell||row.length){row.push(cell);rows.push(row)}return rows}
function importDealerCSV(file){if(!file)return;const r=new FileReader();r.onload=()=>{try{const rows=parseCSV(String(r.result).replace(/^\uFEFF/,''));const head=rows.shift().map(x=>x.trim().replace(/^="(.*)"$/,'$1'));const ix=Object.fromEntries(head.map((h,i)=>[h,i]));const raw=rows.map(r=>({Bestellnummer:(r[ix.Bestellnummer]||'').replace(/^="(.*)"$/,'$1'),Menge:(r[ix.Menge]||'').replace(/^="(.*)"$/,'$1'),EAN:(r[ix.EAN]||'').replace(/^="(.*)"$/,'$1'),Name:(r[ix.Name]||'').replace(/^="(.*)"$/,'$1'),Variante:(r[ix.Variante]||'').replace(/^="(.*)"$/,'$1')}));const keep=raw.map(x=>{const t=(x.Name+' '+x.Variante).toLowerCase();let category='';if(t.includes('elfliq')||(t.includes('elfa')&&t.includes('liquid')))category='ELFA-Liquid';else if(t.includes('einweg'))category='Einwegzigaretten';else if(t.includes('prefilled pod')||t.includes('prefill pod'))category='Prefilled Pods';else if(t.includes('akkuträger')||t.includes('akkutraeger'))category='Akkuträger';return category?{...x,category}:null}).filter(Boolean);S.vapeProducts=keep.map((x,i)=>({id:'CAT'+String(i+1).padStart(5,'0'),name:x.Name,variant:x.Variante,category:x.category,orderNo:x.Bestellnummer,ean:x.EAN,qty:x.Menge}));S.vapeCart=(S.vapeCart||[]).filter(x=>S.vapeProducts.some(p=>p.id===x.productId));save();renderVape();toast(`${S.vapeProducts.length} Vape-Artikel importiert`)}catch{toast('CSV konnte nicht gelesen werden')}};r.readAsText(file,'utf-8')}
function renderVape(){
  const q=($('#vapeSearch')?.value||'').trim().toLowerCase();
  const allPs=S.vapeProducts.filter(p=>[p.name,p.variant,p.category,p.id,p.orderNo,p.ean].join(' ').toLowerCase().includes(q));
  const ps=q?allPs.slice(0,20):[];
  $('#vapeProductCount').textContent=S.vapeProducts.length;
  $('#vapeLeadCount').textContent=S.leads.length;
  $('#vapeQuoteCount').textContent=S.vapeQuotes.length;
  $('#vapeInvoiceCount').textContent=S.vapeInvoices.length;
  if($('#vapeMarkup'))$('#vapeMarkup').value=S.vapeMarkup;
  if($('#vapeMarkupValue'))$('#vapeMarkupValue').textContent=`${S.vapeMarkup}%`;
  const mapped=S.vapeProducts.filter(p=>privateEk(p)).length;
  if($('#vapeL3Status'))$('#vapeL3Status').textContent=Object.keys(S.vapePrivatePrices).length?`${Object.keys(S.vapePrivatePrices).length} L3-Werte geladen · ${mapped} Katalogartikel erkannt`:'Noch keine private L3-Datei geladen';
  const cart=cartItems(),cartNet=cart.reduce((a,x)=>a+x.qty*x.price,0);
  if($('#vapeCartBadge'))$('#vapeCartBadge').textContent=String(cartCount());
  if($('#vapeCart'))$('#vapeCart').innerHTML=cart.length?`<div class="row"><div><b>${cartCount()} Artikel</b><div class="meta">Warenwert netto ${money(cartNet)}</div></div><button class="secondary" data-cart-clear>🗑️ Leeren</button></div>${cart.map(x=>`<div class="row" style="padding:10px 0;border-bottom:1px solid var(--line)"><div><b>${esc(x.description)}</b><div class="meta">${esc(x.variant||'')} · ${money(x.price)} / Stück</div></div><div class="row compact"><button class="secondary" data-cart-minus="${esc(x.productId)}">−</button><b>${x.qty}</b><button class="secondary" data-cart-plus="${esc(x.productId)}">＋</button></div></div>`).join('')}<div class="row" style="margin-top:12px"><b>Netto</b><b>${money(cartNet)}</b></div>`:'<div class="empty">Warenkorb ist leer. Füge Produkte aus dem Katalog hinzu.</div>';
  let catalogHtml;
  if(!q){
    catalogHtml='<div class="empty">Gib oben einen Artikelnamen, eine EAN oder Bestellnummer ein, um Produkte anzuzeigen.</div>';
  }else if(!allPs.length){
    catalogHtml='<div class="empty">Keine Artikel gefunden.</div>';
  }else{
    catalogHtml=`<div class="meta" style="margin:0 0 10px">${allPs.length} Treffer · angezeigt werden maximal 20</div>`+ps.map(p=>{
      const ek=privateEk(p),vk=vapePrice(p);
      return `<article class="card"><div class="row"><div><h3>${esc(p.name)}</h3><div class="meta">${esc(p.variant||'')} · ${esc(p.category)} · ${esc(p.id)}</div></div><span class="badge">+ ${S.vapeMarkup}% EK</span></div><div class="chips"><span class="chip">RRP —</span>${ek!==null?`<span class="chip">EK L3 🔒 ${money(ek)}</span>`:'<span class="chip">EK L3 🔒 —</span>'}<span class="chip good">${vk===null?'VK —':`VK ${money(vk)}`}</span>${ek!==null?`<span class="chip">intern. Aufschlag ${S.vapeMarkup}%</span>`:'<span class="chip">L3-Zuordnung prüfen</span>'}</div><div class="lead-actions"><button ${vk===null?'disabled':''} data-vape-cart="${p.id}">🛒 In Warenkorb</button><button ${vk===null?'disabled':''} data-vape-add="${p.id}">＋ Einzel-Angebot</button></div></article>`;
    }).join('');
  }
  $('#vapeProductList').innerHTML=catalogHtml;
  $('#vapeQuoteList').innerHTML=S.vapeQuotes.map(q=>`<article class="card"><div class="row"><div><h3>${esc(q.number)} · ${esc(q.company)}</h3><div class="meta">${esc(q.date||'')} · ${esc(q.status||'Entwurf')}</div></div><b>${money(q.gross)}</b></div><div class="lead-actions"><button data-vq-edit="${q.id}">✏️ Bearbeiten</button><button data-vq-print="${q.id}">🖨️ Drucken / PDF</button><button data-vq-invoice="${q.id}">🧾 Rechnung</button></div></article>`).join('')||'<div class="empty">Noch keine Vape-Angebote.</div>';
  $('#vapeInvoiceList').innerHTML=S.vapeInvoices.map(i=>`<article class="card"><div class="row"><div><h3>${esc(i.number)} · ${esc(i.company)}</h3><div class="meta">${esc(i.date||'')} · fällig ${esc(i.due||'')}</div></div><b>${money(i.gross)}</b></div><div class="lead-actions"><button data-vi-edit="${i.id}">✏️ Bearbeiten</button><button data-vi-print="${i.id}">🖨️ Drucken / PDF</button></div></article>`).join('')||'<div class="empty">Noch keine Vape-Rechnungen.</div>';
}
